function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length !== nums2.length) return 'nums1 and nums2 need the same length.';
  if (nums1.length < 1 || nums1.length > 100000) return 'The arrays need 1 to 10^5 values.';
  if (nums1.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value of nums1 is between 1 and 100.';
  if (nums2.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value of nums2 is between 1 and 100.';
  return null;
}

