function minProductSum(nums1, nums2) {
  const small = [...nums1].sort((a, b) => a - b);
  const large = [...nums2].sort((a, b) => b - a);
  let total = 0;

  for (let i = 0; i < small.length; i++) {
    total += small[i] * large[i];
  }
  return total;
}

