function minProductSum(nums1, nums2) {
  // Try every ordering of nums1.
  const n = nums1.length;
  const used = new Array(n).fill(false);
  let best = Infinity;
  const place = (pos, sum) => {
    if (pos === n) { best = Math.min(best, sum); return; }
    for (let k = 0; k < n; k++) {
      if (used[k]) continue;
      used[k] = true;
      place(pos + 1, sum + nums1[k] * nums2[pos]);
      used[k] = false;
    }
  };
  place(0, 0);
  return best;
}

